package com.siam.deviceinfo;import android.os.*;import android.content.*;import android.content.pm.*;import android.provider.Settings;import android.net.Uri;import java.util.*;
public class PermissionActivity extends BaseScreenActivity {protected int layout(){return R.layout.activity_permission;}protected String title(){return "নিরাপত্তা ও অনুমতি";}public void onCreate(Bundle b){super.onCreate(b);heading("অ্যাপ ও অনুমতি");note("অন্য অ্যাপের permission toggle এই অ্যাপ থেকে নিয়ন্ত্রণ করা Android-এ নিষিদ্ধ। এখানে অ্যাপের system App info খোলা যাবে, সেখান থেকে আপনি নিজে বদলাতে পারবেন।");PackageManager pm=getPackageManager();for(ApplicationInfo a:pm.getInstalledApplications(0)){if(pm.getLaunchIntentForPackage(a.packageName)!=null){String name=pm.getApplicationLabel(a).toString();action(name+" — App info",()->{try{startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+a.packageName)));}catch(Exception e){note("সেটিংস খোলা যায়নি।");}});}}note("Fake charger যাচাই করার কোনো নির্ভরযোগ্য public Android API নেই; অনিরাপদ hardware diagnostic এড়িয়ে চলুন।");}
}
